select departments.id, departments.dept_name, count(employees.id) as employee_count, round((100 * sum(case when employees.job_title = 'Designer' then 1 else 0 end)) / count(*), 1) as pct_designer, max(employees.salary) - min(employees.salary) as salary_range from departments left outer join employees on departments.id = employees.dept_id group by departments.id, departments.dept_name order by departments.id
